const body = $input.first().json.body || {};
const kind = body.pedido_id ? 'compra' : 'lead';

// Mapeamento da escada de valor → estágio do funil RD Station CRM.
// Ajustar os IDs de estágio conforme o funil real do CRM (substituir CONFIGURE_*).
const tierMap = {
  'conteudo-gratuito':    { tier: 1, tier_label: 'Tráfego / Isca',  stage_id: 'CONFIGURE_STAGE_SEM_CONTATO' },
  'ebook-codigos':        { tier: 2, tier_label: 'Entrada',         stage_id: 'CONFIGURE_STAGE_CONTATO_FEITO' },
  'comunidade':           { tier: 3, tier_label: 'Comunidade',      stage_id: 'CONFIGURE_STAGE_CONTATO_FEITO' },
  'curso-online':         { tier: 4, tier_label: 'Curso Online',    stage_id: 'CONFIGURE_STAGE_IDENTIFICACAO' },
  'acompanhamento-grupo': { tier: 5, tier_label: 'High Ticket',     stage_id: 'CONFIGURE_STAGE_APRESENTACAO' },
  'mentoria-individual':  { tier: 6, tier_label: 'Ultra High',      stage_id: 'CONFIGURE_STAGE_APRESENTACAO' },
};

const tierInfo = tierMap[body.produto_slug] || { tier: 0, tier_label: 'Lead', stage_id: 'CONFIGURE_STAGE_SEM_CONTATO' };

const phoneDigits = String(body.telefone || '').replace(/\D/g, '');

// Payload para POST /api/v1/contacts (RD Station CRM)
const contactPayload = {
  contact: {
    name: body.nome,
    emails: body.email ? [{ email: body.email }] : [],
    phones: phoneDigits ? [{ phone: phoneDigits, type: 'cellphone' }] : [],
    title: body.ocupacao || undefined,
  }
};

// Payload para POST /api/v1/deals (apenas em compra)
const dealPayload = kind === 'compra' ? {
  deal: {
    name: `${body.produto_nome} — ${body.nome}`,
    deal_stage_id: tierInfo.stage_id,
    user_id: 'CONFIGURE_USER_ID_RESPONSAVEL',
  },
  deal_products: [{
    name: body.produto_nome,
    amount: 1,
    price: body.valor,
  }],
  deal_custom_fields: [
    { custom_field_id: 'CONFIGURE_CF_TIER',            value: String(tierInfo.tier) },
    { custom_field_id: 'CONFIGURE_CF_FORMA_PAGAMENTO', value: body.forma_pagamento },
    { custom_field_id: 'CONFIGURE_CF_PEDIDO_ID',       value: body.pedido_id },
  ]
} : null;

return [{
  json: {
    kind,
    tx_id: body.tx_id || null,
    raw: body,
    contactPayload,
    dealPayload,
    tierInfo,
  }
}];
